import Rollbar from 'rollbar';

const rollbarBaseConfig: Rollbar.Configuration = {
  verbose: true, // This will now log as well as Rollbar
  captureUncaught: true, // reports all uncaught exceptions to rollbar by default
  captureUnhandledRejections: true,
  enabled: true,
  payload: {
    code_version: process.env.NEXT_PUBLIC_CODE_VERSION,
    environment: process.env.APP_ENV,
    client: {
      javascript: {
        guess_uncaught_frames: true, // catch errors frames when the browser does not provide error's line and column numbers,
        source_map_enabled: true,
        code_version: process.env.NEXT_PUBLIC_CODE_VERSION
      },
    },
  },
  // will ignore ChunkLoadError and AbortError
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  checkIgnore: (isUncaught: boolean, args: any[], item: any) => {
    // Check if the error is an Error object or error-like object
    const error = args[0];

    // Log for debugging what we're receiving in non-production
    if (process.env.NODE_ENV !== 'production') {
      // eslint-disable-next-line no-console
      console.log('[Rollbar checkIgnore]', {
        isUncaught,
        errorName: error?.name,
        errorConstructor: error?.constructor?.name,
        errorMessage: error?.message,
        errorType: typeof error,
        itemClass: item?.body?.trace?.exception?.class,
        itemMessage: item?.body?.trace?.exception?.message,
      });
    }

    // Check both the error argument and the item payload
    if (isUncaught && (error || item)) {
      // First check the error argument
      if (error) {
        // Ignore ChunkLoadError (webpack code splitting errors)
        if (error.name === 'ChunkLoadError' ||
            error.constructor?.name === 'ChunkLoadError' ||
            (typeof error.message === 'string' && error.message.includes('Loading chunk'))) {
          return true;
        }

        // Ignore AbortError (intentional request cancellations)
        if (error.name === 'AbortError' || error.constructor?.name === 'AbortError') {
          return true;
        }

        // Ignore generic Network Error (usually from Axios)
        // These are typically due to network connectivity issues, timeouts, or CORS
        if (error.name === 'Error' && error.message === 'Network Error') {
          return true;
        }
        if (typeof error.message === 'string' && error.message === 'Network Error') {
          return true;
        }

        // Ignore "Request aborted" errors (user navigation, tab close, etc.)
        if (typeof error.message === 'string' && error.message.includes('Request aborted')) {
          return true;
        }
      }

      // Also check the item payload (Rollbar's internal representation)
      const exception = item?.body?.trace?.exception;
      if (exception) {
        // Ignore ChunkLoadError
        if (exception.class === 'ChunkLoadError' ||
            (typeof exception.message === 'string' && exception.message.includes('Loading chunk'))) {
          return true;
        }

        // Ignore AbortError (including DOMException abort errors)
        if (exception.class === 'AbortError' ||
            (typeof exception.message === 'string' &&
             (exception.message.includes('signal is aborted') ||
              exception.message.includes('The user aborted a request')))) {
          return true;
        }

        // Ignore ResizeObserver errors (browser noise, not actionable)
        if (typeof exception.message === 'string' &&
            exception.message.includes('ResizeObserver loop')) {
          return true;
        }

        // Ignore Network Error in item payload
        if (exception.class === 'Error' && exception.message === 'Network Error') {
          return true;
        }

        // Ignore "Request aborted" errors in item payload
        if (typeof exception.message === 'string' && exception.message.includes('Request aborted')) {
          return true;
        }
      }

      // Ignore video playback errors that are outside of our control
      const messageBody = item?.body?.message?.body;
      const customData = item?.body?.message?.extra;
      if (typeof messageBody === 'string' && messageBody === 'Video playback error' && customData) {
        const mediaError = customData?.mediaError;
        // Ignore these browser/network-related errors that we can't fix:
        // - MEDIA_ERR_ABORTED (code 1): User aborted the video load
        // - MEDIA_ERR_NETWORK (code 2): Network error while loading
        // - MEDIA_ERR_SRC_NOT_SUPPORTED (code 4): Browser codec/format limitation
        // We still report MEDIA_ERR_DECODE (code 3) as it might indicate video corruption
        if (mediaError?.code === 1 || mediaError?.code === 2 || mediaError?.code === 4) {
          return true;
        }
        if (typeof mediaError?.type === 'string' &&
            (mediaError.type.includes('MEDIA_ERR_ABORTED') ||
             mediaError.type.includes('MEDIA_ERR_NETWORK') ||
             mediaError.type.includes('MEDIA_ERR_SRC_NOT_SUPPORTED'))) {
          return true;
        }
      }

      // Ignore third-party script errors (LinkedIn, etc.)
      const frames = item?.body?.trace?.frames;
      if (frames && Array.isArray(frames)) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const hasThirdPartyOrigin = frames.some((frame: any) => {
          const filename = frame?.filename || '';
          return filename.includes('snap.licdn.com') ||
                 filename.includes('linkedin.com');
        });
        if (hasThirdPartyOrigin) {
          return true;
        }
      }
    }
    return false;
  }
};

const rollbarConfig = {
  ...rollbarBaseConfig,
  accessToken: process.env.ROLLBAR_POST_CLIENT_ITEM,
};

const rollbarTrackingConfig = {
  ...rollbarBaseConfig,
  accessToken: process.env.IDH_ROLLBAR_POST_CLIENT_ITEM,
  captureUnhandledRejections: false,
  captureUncaught: false,
};

export const rollbar = new Rollbar(rollbarConfig);

export const rollbarTracking = new Rollbar(rollbarTrackingConfig);