import { DOMChanges } from "./types"

export class VideoContentReplayError extends Error {
	constructor() {
		super( 'Replay content is a video, not DOM changes' )
		this.name = 'VideoContentReplayError'
	}
}

export const fetchReplayData = async ( s3File: string ): Promise<DOMChanges[]> => {
	const res = await fetch( s3File )
	const contentType = res.headers.get( 'content-type' ) || ''
	if ( contentType.includes( 'video' ) ) {
		throw new VideoContentReplayError()
	}
	const blob = await res.blob()
	const stream = blob.stream()

	// eslint-disable-next-line no-undef
	const chunks: BlobPart[] = []

	await stream
		.pipeThrough(
			// eslint-disable-next-line @typescript-eslint/no-explicit-any
			new ( window as any ).DecompressionStream( 'gzip' )
		)
		.pipeTo(
			new WritableStream( {
				write( chunk ) {
					chunks.push( chunk as Blob )
				}
			} )
		)

	const merged = await new Blob( chunks, { type: 'text/plain' } ).text()

	return JSON.parse( merged )
}

export const triggerEvent = ( el: HTMLElement, type: string, detail: unknown = {} ): void => {
	const event = new CustomEvent( type, {
		detail,
	} )
	setTimeout( () => el.dispatchEvent( event ), 0 )
	// eslint-disable-next-line no-console
	console.debug( `Triggered event: ${ type }` )
}

// ============================================================================
// [CSS RECORD] In-session CSS dedup ref resolution.
//
// The SDK (recordStylesheets) ships each CSS payload >= 1KB (style text, serialized
// sheet rules, CSS_REPLACE text, adopted-sheet rules) once per session; identical
// repeats arrive as an `@uxc-css-ref:<key>` marker. This pass materializes the bodies
// back in place so the rest of the player never sees a ref. Two passes over the whole
// stream (collect bodies, then resolve) so it does not depend on event order, and it
// runs once at load time so seeking/re-applying slices stays safe.
//
// The key MUST byte-match the SDK: cyrb53(text).toString(36) + '-' + length.toString(36).
// ============================================================================

const CSS_REF_PREFIX = '@uxc-css-ref:'
const CSS_DEDUP_MIN_BYTES = 1024

/* eslint-disable no-bitwise */
// Byte-exact port of the SDK's cyrb53 hash — the bitwise ops here MUST match the
// recorder, so this block intentionally opts out of the no-bitwise rule.
const cyrb53 = ( str: string, seed = 0 ): number => {
	let h1 = 0xdeadbeef ^ seed
	let h2 = 0x41c6ce57 ^ seed
	for ( let i = 0; i < str.length; i += 1 ) {
		const ch = str.charCodeAt( i )
		h1 = Math.imul( h1 ^ ch, 2654435761 )
		h2 = Math.imul( h2 ^ ch, 1597334677 )
	}
	h1 = Math.imul( h1 ^ ( h1 >>> 16 ), 2246822507 )
	h1 ^= Math.imul( h2 ^ ( h2 >>> 13 ), 3266489909 )
	h2 = Math.imul( h2 ^ ( h2 >>> 16 ), 2246822507 )
	h2 ^= Math.imul( h1 ^ ( h1 >>> 13 ), 3266489909 )
	return 4294967296 * ( 2097151 & h2 ) + ( h1 >>> 0 )
}
/* eslint-enable no-bitwise */
const cssContentKey = ( text: string ): string => `${ cyrb53( text ).toString( 36 ) }-${ text.length.toString( 36 ) }`

// Loose structural views over the min/full event and node shapes — the walker only
// touches the CSS carrier fields and treats everything else as opaque.
interface AnyCssRule { rule?: string, r?: string }
interface AnyNode {
	a?: { textContent?: string },
	attributes?: { textContent?: string },
	c?: AnyNode[],
	childNodes?: AnyNode[],
	r?: AnyCssRule[],
	cssRules?: AnyCssRule[],
}
interface AnySheet { r?: AnyCssRule[], rules?: AnyCssRule[] }
interface AnyChange {
	ct?: string, type?: string,
	n?: AnyNode, node?: AnyNode,
	c?: AnyNode[], children?: AnyNode[],
	tx?: string, text?: string,
	sh?: AnySheet[], sheets?: AnySheet[],
}

const isCssRef = ( s: string ): boolean => s.startsWith( CSS_REF_PREFIX )

/**
 * Resolve every `@uxc-css-ref:` marker in a session's change stream to the body it
 * refers to. Mutates the changes in place and returns the same array. Idempotent and
 * a no-op on sessions recorded without dedup (no markers present).
 */
export const resolveCssDedupRefs = ( changes: unknown[] ): unknown[] => {
	const dict = new Map<string, string>()
	let unresolved = 0

	const eachCarrier = ( change: AnyChange, visit: {
		text: ( value: string, set: ( next: string ) => void ) => void,
		ruleBlock: ( rules: AnyCssRule[] ) => void,
	} ) => {
		const walkNode = ( node: AnyNode ) => {
			if ( !node || typeof node !== 'object' ) { return }
			const attrs = node.a ?? node.attributes
			if ( attrs && typeof attrs.textContent === 'string' ) {
				visit.text( attrs.textContent, ( next ) => { attrs.textContent = next } )
			}
			const rules = node.r ?? node.cssRules
			if ( rules && rules.length ) { visit.ruleBlock( rules ) }
			const children = node.c ?? node.childNodes
			if ( children ) { children.forEach( walkNode ) }
		}

		const kind = change.type ?? change.ct
		if ( kind === 'PAGE_LOAD' || kind === '13' || kind === 'IFRAME_LOAD' || kind === '26' ) {
			// PAGE_LOAD and IFRAME_LOAD both carry a full document snapshot under node/n.
			const root = change.node ?? change.n
			if ( root ) { walkNode( root ) }
		} else if ( kind === 'ADD_NODES' || kind === '4' ) {
			const children = change.children ?? change.c
			if ( children ) { children.forEach( walkNode ) }
		} else if ( kind === 'CSS_REPLACE' || kind === '28' ) {
			const value = change.text ?? change.tx
			if ( typeof value === 'string' ) {
				visit.text( value, ( next ) => {
					if ( change.text !== undefined ) {
						// eslint-disable-next-line no-param-reassign
						change.text = next
					} else {
						// eslint-disable-next-line no-param-reassign
						change.tx = next
					}
				} )
			}
		} else if ( kind === 'ADOPTED_STYLE_SHEET' || kind === '29' ) {
			const sheets = change.sheets ?? change.sh
			if ( sheets ) {
				sheets.forEach( ( sheet ) => {
					const rules = sheet.rules ?? sheet.r
					if ( rules && rules.length ) { visit.ruleBlock( rules ) }
				} )
			}
		}
	}

	const ruleText = ( rule: AnyCssRule ): string => rule.rule ?? rule.r ?? ''
	const setRuleText = ( rule: AnyCssRule, next: string ) => {
		if ( rule.rule !== undefined ) {
			// eslint-disable-next-line no-param-reassign
			rule.rule = next
		} else {
			// eslint-disable-next-line no-param-reassign
			rule.r = next
		}
	}
	const isRefBlock = ( rules: AnyCssRule[] ): boolean => rules.length === 1 && isCssRef( ruleText( rules[0] ) )

	// Pass 1 — collect every literal body under its content key.
	changes.forEach( ( change ) => {
		eachCarrier( change as AnyChange, {
			text: ( value ) => {
				if ( !isCssRef( value ) && value.length >= CSS_DEDUP_MIN_BYTES ) { dict.set( cssContentKey( value ), value ) }
			},
			ruleBlock: ( rules ) => {
				if ( isRefBlock( rules ) ) { return }
				const joined = rules.map( ruleText ).join( '\n' )
				if ( joined.length >= CSS_DEDUP_MIN_BYTES ) { dict.set( cssContentKey( joined ), joined ) }
			},
		} )
	} )

	// Pass 2 — materialize refs. A single-ref rule block expands to one entry carrying
	// the whole sheet text (the player joins rule entries, so the outcome is identical).
	//
	// An unresolvable ref (its body is in a frame the player did not receive) never leaks
	// the raw marker into the replayed DOM:
	//  - style text     → blanked (the style is missing either way, but stays clean)
	//  - rule block     → emptied, which matters for <link> carriers: a link without rules
	//                     falls back to fetching its href, restoring the real stylesheet
	//  - CSS_REPLACE    → dropped, so the carrier keeps whatever CSS it already had
	const lookup = ( ref: string ): string | null => {
		const body = dict.get( ref.slice( CSS_REF_PREFIX.length ) )
		if ( body === undefined ) { unresolved += 1; return null }
		return body
	}
	const dropped: unknown[] = []
	changes.forEach( ( change ) => {
		eachCarrier( change as AnyChange, {
			text: ( value, set ) => {
				if ( !isCssRef( value ) ) { return }
				const body = lookup( value )
				const kind = ( change as AnyChange ).type ?? ( change as AnyChange ).ct
				if ( body !== null ) {
					set( body )
				} else if ( kind === 'CSS_REPLACE' || kind === '28' ) {
					dropped.push( change )
				} else {
					set( '' )
				}
			},
			ruleBlock: ( rules ) => {
				if ( !isRefBlock( rules ) ) { return }
				const body = lookup( ruleText( rules[0] ) )
				if ( body !== null ) {
					setRuleText( rules[0], body )
				} else {
					// eslint-disable-next-line no-param-reassign
					rules.length = 0
				}
			},
		} )
	} )
	if ( dropped.length ) {
		dropped.forEach( ( change ) => {
			const index = changes.indexOf( change )
			if ( index !== -1 ) { changes.splice( index, 1 ) }
		} )
	}

	if ( unresolved > 0 ) {
		// eslint-disable-next-line no-console
		console.warn( `[CSS RECORD] ${ unresolved } CSS dedup ref(s) had no body in this session — affected styles will be missing` )
	}
	return changes
}
