/* eslint-disable no-use-before-define */
export interface INodeCSSRule {
	rule: string
	index: number | number[]
	targetStyle: string
}

export interface INodeCSSRuleMin {
	r: string
	i: number | number[]
	t: string
}

export interface INode {
	id?: string
	nodeName: string
	tagName: string
	attributes: Record<string, string>
	UUID: string
	childNodes: INode[],
	cssRules: INodeCSSRule[] // only for style elements
	isSVG: boolean,
	nodeType: number,
	meta?: IMGMeta | VideoMeta | IframeMeta
	// [SHADOW DOM] element hosts a shadow root (its shadow children follow in childNodes)
	isShadowHost?: boolean
	// [SHADOW DOM] node is a direct child of a shadow root → append into host.shadowRoot
	isShadow?: boolean
}

export interface INodeMin {
	i?: string
	nn: string
	t: string
	a: Record<string, string>
	u: string
	c: INodeMin[]
	r: INodeCSSRuleMin[]
	s: boolean
	nt: number
	m?: IMGMetaMin | VideoMetaMin | IframeMetaMin
	// [SHADOW DOM] sh = isShadowHost, sd = isShadow (direct shadow-root child)
	sh?: boolean
	sd?: boolean
}

// eslint-disable-next-line no-shadow
export enum ChangeType {
	WINDOW_RESIZE = '1',
	CUSTOM_EVENT = '2',
	DOM_READY = '3',
	ADD_NODES = '4',
	ATTR_CHANGE = '5',
	REMOVE_NODES = '6',
	SCROLL = '7',
	FOCUS = '8',
	MOUSE_MOVE = '9',
	TOUCH = '9.1e', // experimental
	MOUSE_CLICK = '10',
	MOUSE_OVER = '11',
	MOUSE_OUT = '12',
	PAGE_LOAD = '13',
	CHARACTER_DATA_CHANGE = '14',
	CSS_INSERT_RULE = '15',
	CSS_DELETE_RULE = '16',
	URL_CHANGE = '17',
	INPUT_CHANGE = '18',
	CHECKED_CHANGE = '18.c',
	USER_PROPERTY = '19',
	EVENT = '20',
	CLIENT_IP = '21',
	MEDIA_INFO = '22',
	IFRAME_LOAD = '26',
	// [CSS RECORD] emitted only when the SDK enableCSSRecord flag is on
	CSS_REPLACE = '28',           // CSSStyleSheet.replace / replaceSync (whole-sheet swap)
	ADOPTED_STYLE_SHEET = '29',   // document/shadowRoot adoptedStyleSheets (constructable sheets)
	CSS_STYLE_DECLARATION = '30', // setProperty / removeProperty on a rule declaration block
}

