export type CSSChanges = CSSInsertRule | CSSDeleteRule | CSSReplace | AdoptedStyleSheet | CSSStyleDeclarationChange
export type CSSChangesMin = CSSInsertRuleMin | CSSDeleteRuleMin | CSSReplaceMin | AdoptedStyleSheetMin | CSSStyleDeclarationChangeMin

export type DOMChanges = AddNodes | AttrChange | RemoveNodes | ScrollChange | FocusChange | MouseMoveChange | MouseClickChange | MouseOverChange | MouseOutChange | PageLoad | CharacterDataChange | WindowResize | CSSChanges | URLChange | InputChange | UserProperty | SessionEvent | ClientIp | DomReady | MediaInfo | TouchChange | CheckedChange | IframeLoad
export type DOMChangesMin = AddNodesMin | AttrChangeMin | RemoveNodesMin | ScrollChangeMin | FocusChangeMin | MouseMoveChangeMin | MouseClickChangeMin | MouseOverChangeMin | MouseOutChangeMin | PageLoadMin | CharacterDataChangeMin | WindowResizeMin | CSSChangesMin | URLChangeMin | InputChangeMin | UserPropertyMin | SessionEventMin | ClientIpMin | DomReadyMin | MediaInfoMin | TouchChangeMin | CheckedChangeMin | IframeLoadMin

export type TVideoEvents = 'play' | 'pause' | 'seeked' | 'error' | 'ratechange' | 'ended' | 'loadedmetadata' | 'timeupdate' | 'canplaythrough' | 'contentresize' | 'urlchange' | 'frameloaded' | 'csserror'

export interface IVideoInterface {
	play(): Promise<void>
	pause(): Promise<void>
	seekTo( time: number ): Promise<void>
	set currentTime( newValue: number )
	get currentTime(): number
	get duration(): number
	get paused(): boolean
	get playbackRate(): number
	set playbackRate( rate: number )
	get ended(): boolean
	get width(): number
	get height(): number
	get videoWidth(): number
	get videoHeight(): number
	get readyState(): number

	addEventListener: ( event: TVideoEvents, callback: () => void ) => void
	removeEventListener: ( event: TVideoEvents, callback: () => void ) => void

	__domElement: HTMLElement;
}